class Solution {
public:
    vector<string> divideString(string s, int k, char fill) {
        vector<string> result;
        int n = s.size();
        for (int i = 0; i < n; i += k) {
            result.emplace_back();
            string& group = result.back();
            int end = i + k < n ? i + k : n;
            group.append(s, i, end - i);
            while ((int)group.size() < k) {
                group.push_back(fill);
            }
        }
        return result;
    }
};
